// Nexora AI: one Cloudflare Worker. Two access codes: first opens a book library, second opens the AI assistant and games.
// Needs a Workers AI binding named "AI". Optional variables: PASSWORD (default 6677) and PASSWORD2 (default 1111).
const DEFAULT_CODE1 = '6677';
const DEFAULT_CODE2 = '1111';
