const json = (o, status = 200, extra = {}) =>
  new Response(JSON.stringify(o), { status, headers: { 'content-type': 'application/json', ...BASE, ...extra } });
const page = body => new Response(body, { headers: { 'content-type': 'text/html; charset=utf-8', ...BASE } });

const enc = new TextEncoder();
const hex = buf => [...new Uint8Array(buf)].map(b => b.toString(16).padStart(2, '0')).join('');
const code1 = env => String((env && env.PASSWORD) || DEFAULT_CODE1);
const code2 = env => String((env && env.PASSWORD2) || DEFAULT_CODE2);
async function token(stage, env) {
  const key = await crypto.subtle.importKey('raw', enc.encode('nexora-v2|' + stage + '|' + code1(env) + '|' + code2(env)), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  return hex(await crypto.subtle.sign('HMAC', key, enc.encode('authorized-' + stage)));
}
function same(a, b) {
  if (a.length !== b.length) return false;
  let d = 0; for (let i = 0; i < a.length; i++) d |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return d === 0;
}
const cookieOf = (request, name) => { const m = new RegExp('(?:^|;\\s*)' + name + '=([a-f0-9]+)').exec(request.headers.get('cookie') || ''); return m ? m[1] : ''; };
// 0 = locked, 1 = library, 2 = assistant + games
async function stageOf(request, env) {
  if (!same(cookieOf(request, 'nx_a'), await token('a', env))) return 0;
  if (!same(cookieOf(request, 'nx_b'), await token('b', env))) return 1;
  return 2;
}
const setCookie = (name, value, age) => `${name}=${value}; Path=/; Max-Age=${age}; HttpOnly; Secure; SameSite=Strict`;
const sleep = ms => new Promise(r => setTimeout(r, ms));
// Finds the Workers AI binding: normally "AI", but any binding that has a run() function works.
function aiOf(env) {
  if (env && env.AI && typeof env.AI.run === 'function') return env.AI;
  for (const k of Object.keys(env || {})) { const v = env[k]; if (v && typeof v === 'object' && typeof v.run === 'function') return v; }
  return null;
}
function aiProblem(env) {
  if (env && env.AI !== undefined) return 'A binding named AI exists but it is not a Workers AI binding (it is a ' + typeof env.AI + '). In Settings > Bindings, delete it, then Add > Workers AI and name it AI. Do not add it as a text variable.';
  return 'Workers AI is not connected. In this Worker open Settings > Bindings > Add > Workers AI, name it AI, then deploy.';
}
function badOrigin(request, url) {
  const o = request.headers.get('origin');
  if (!o) return false;
  try { return new URL(o).host !== url.host; } catch { return true; }
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const p = url.pathname;

    if (p === '/robots.txt') return new Response('User-agent: *\nDisallow: /\n', { headers: { 'content-type': 'text/plain', ...BASE } });

    if (p === '/api/login' || p === '/api/unlock') {
      if (request.method !== 'POST') return json({ error: 'Method not allowed' }, 405);
      if (badOrigin(request, url)) return json({ error: 'Bad origin' }, 403);
      const second = p === '/api/unlock';
      if (second && (await stageOf(request, env)) < 1) return json({ error: 'Locked' }, 401);
      let body = {}; try { body = await request.json(); } catch {}
      const given = String(body.code || '').slice(0, 64), want = second ? code2(env) : code1(env);
      if (given.length === want.length && same(given, want)) {
        return json({ ok: true }, 200, { 'set-cookie': setCookie(second ? 'nx_b' : 'nx_a', await token(second ? 'b' : 'a', env), 2592000) });
      }
      await sleep(1500);
      return json({ error: 'Wrong code' }, 401);
    }

    if (p === '/api/logout') {
      const h = new Headers({ 'content-type': 'application/json', ...BASE });
      h.append('set-cookie', setCookie('nx_a', '', 0)); h.append('set-cookie', setCookie('nx_b', '', 0));
      return new Response('{"ok":true}', { headers: h });
    }

    if (p === '/api/search') {
      if ((await stageOf(request, env)) < 2) return json({ error: 'Locked' }, 401);
      const q = (url.searchParams.get('q') || '').trim().slice(0, 150);
      if (!q) return json({ items: [] });
      const u = new URL('https://api.duckduckgo.com/');
      u.searchParams.set('q', q); u.searchParams.set('format', 'json'); u.searchParams.set('no_html', '1'); u.searchParams.set('skip_disambig', '1'); u.searchParams.set('t', 'nexora');
      try {
        const r = await fetch(u, { headers: { 'user-agent': 'NexoraSearch/1.0' }, signal: AbortSignal.timeout(8000) });
        if (!r.ok) return json({ error: 'Search returned an error (' + r.status + ').' }, 502);
        const d = await r.json(); const items = [];
        const add = (t, x, l) => { if (t && /^https?:\/\//.test(l || '')) items.push({ t: String(t).slice(0, 160), x: String(x || '').slice(0, 400), u: l }); };
        if (d.AbstractText) add(d.Heading || q, d.AbstractText, d.AbstractURL);
        if (d.Answer && typeof d.Answer === 'string') items.unshift({ t: 'Answer', x: d.Answer.slice(0, 400), u: '' });
        const walk = a => (a || []).forEach(o => { if (o.Topics) walk(o.Topics); else add((o.Text || '').split(' - ')[0], o.Text, o.FirstURL); });
        walk(d.RelatedTopics);
        return json({ items: items.slice(0, 12) });
      } catch { return json({ error: 'Could not reach DuckDuckGo. Try again.' }, 502); }
    }

    if (p === '/api/books') {
      if ((await stageOf(request, env)) < 1) return json({ error: 'Locked' }, 401);
      const q = (url.searchParams.get('q') || '').trim().slice(0, 100);
      if (!q) return json({ docs: [] });
      const u = new URL('https://openlibrary.org/search.json');
      u.searchParams.set('q', q); u.searchParams.set('limit', '24');
      u.searchParams.set('fields', 'key,title,author_name,first_publish_year,cover_i,ebook_access');
      try {
        const r = await fetch(u, { headers: { 'user-agent': 'NexoraLibrary/1.0' }, signal: AbortSignal.timeout(8000) });
        if (!r.ok) return json({ error: 'The book service returned an error (' + r.status + '). Try again.' }, 502);
        const d = await r.json();
        return json({ docs: (d.docs || []).slice(0, 24).map(x => ({ key: x.key, title: x.title, authors: (x.author_name || []).slice(0, 2), year: x.first_publish_year || null, cover: x.cover_i || null, free: x.ebook_access === 'public' })) });
      } catch { return json({ error: 'Could not reach the book service. Try again.' }, 502); }
    }

    if (p === '/api/chat') {
      if ((await stageOf(request, env)) < 2) return json({ error: 'Locked' }, 401);
      const AI = aiOf(env);
      if (request.method === 'GET') return json({ ok: true, ai: !!AI, note: AI ? undefined : aiProblem(env) });
      if (request.method !== 'POST') return json({ error: 'Method not allowed' }, 405);
      if (badOrigin(request, url)) return json({ error: 'Bad origin' }, 403);
      if (!AI) return json({ error: aiProblem(env) }, 500);

      let body;
      try { body = await request.json(); } catch { return json({ error: 'Bad request' }, 400); }
      const msgs = (Array.isArray(body.messages) ? body.messages : [])
        .filter(m => m && (m.role === 'user' || m.role === 'assistant') && typeof m.content === 'string' && m.content)
        .slice(-20)
        .map(m => ({ role: m.role, content: m.content.slice(0, 30000) }));
      if (!msgs.length || msgs[msgs.length - 1].role !== 'user') return json({ error: 'No message to answer' }, 400);
      const system = String(body.system || '').slice(0, 4000);

      const imgs = (Array.isArray(body.images) ? body.images : [])
        .filter(s => typeof s === 'string' && s.length < 2000000 && /^data:image\/(jpeg|png|webp|gif);base64,[A-Za-z0-9+\/=]+$/.test(s)).slice(0, 3);
      if (imgs.length) {
        const lastMsg = msgs[msgs.length - 1];
        lastMsg.content = [{ type: 'text', text: lastMsg.content.slice(0, 8000) }, ...imgs.map(u => ({ type: 'image_url', image_url: { url: u } }))];
      }
      let last = 'No model available';
      for (const model of (imgs.length ? VISION_MODELS : MODELS)) {
        for (let attempt = 0; attempt < 2; attempt++) {
          try {
            const stream = await AI.run(model, { messages: [{ role: 'system', content: system }, ...msgs], stream: true, max_tokens: 1500 });
            return new Response(stream, { headers: { 'content-type': 'text/event-stream', ...BASE } });
          } catch (e) {
            last = String((e && e.message) || e).slice(0, 200);
            if (attempt === 0 && /agree|licen[sc]e/i.test(last) && model.includes('llama-3.2')) { try { await AI.run(model, { prompt: 'agree' }); } catch {} continue; }
            break;
          }
        }
        if (/limit|quota|capacity|429/i.test(last)) break;
        if (!imgs.length && !RETIRED.test(last)) break;
      }
      return json({ error: last }, /limit|quota|capacity|429/i.test(last) ? 429 : 500);
    }

    if (request.method !== 'GET' && request.method !== 'HEAD') return new Response('Method not allowed', { status: 405 });
    const s = await stageOf(request, env);
    return page(s === 2 ? HTML : s === 1 ? LIBRARY : LOGIN);
  }
};
